pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testRegression_property() public {
        bytes32 assertionId = keccak256("test");
        c.assertionDisputedCallback(assertionId);
        (,,, bool validateDisputers) = abi.decode(abi.encode(c.getAssertionPolicy(assertionId)), (bool,bool,bool,bool));
        assertTrue(validateDisputers == false);
    }
}
